BEGIN TRANSACTION;
CREATE TABLE alembic_version (
	version_num VARCHAR(32) NOT NULL, 
	CONSTRAINT alembic_version_pkc PRIMARY KEY (version_num)
);
CREATE TABLE app_settings (
	id INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, 
	setting_key VARCHAR(100) NOT NULL, 
	setting_value TEXT NOT NULL, 
	updated_at VARCHAR(50)
);
CREATE TABLE documents (
	id INTEGER NOT NULL, 
	file_id VARCHAR(50) NOT NULL, 
	filename VARCHAR(255) NOT NULL, 
	upload_date VARCHAR(50), 
	total_topics INTEGER NOT NULL, 
	total_pages INTEGER NOT NULL, 
	analysis_path TEXT NOT NULL, 
	formatted_path TEXT, 
	created_at VARCHAR(50), 
	PRIMARY KEY (id)
);
CREATE TABLE questions (
	id INTEGER NOT NULL, 
	document_id INTEGER NOT NULL, 
	topic_id INTEGER NOT NULL, 
	topic_name TEXT NOT NULL, 
	question_type VARCHAR(50) NOT NULL, 
	difficulty VARCHAR(50) NOT NULL, 
	question_text TEXT NOT NULL, 
	options_json TEXT NOT NULL, 
	correct_answer VARCHAR(50) NOT NULL, 
	explanation TEXT NOT NULL, 
	key_terms_json TEXT, 
	regulatory_context TEXT, 
	pages VARCHAR(50), 
	times_seen INTEGER, 
	times_correct INTEGER, 
	created_at VARCHAR(50), 
	PRIMARY KEY (id), 
	FOREIGN KEY(document_id) REFERENCES documents (id) ON DELETE CASCADE
);
CREATE TABLE spaced_repetition (
	id INTEGER NOT NULL, 
	question_id INTEGER NOT NULL, 
	ease_factor FLOAT, 
	interval_days INTEGER, 
	repetitions INTEGER, 
	next_review_date DATE NOT NULL, 
	last_reviewed VARCHAR(50), 
	total_reviews INTEGER, 
	correct_reviews INTEGER, 
	PRIMARY KEY (id), 
	FOREIGN KEY(question_id) REFERENCES questions (id) ON DELETE CASCADE
);
DELETE FROM "sqlite_sequence";
CREATE TABLE study_sessions (
	id INTEGER NOT NULL, 
	document_id INTEGER NOT NULL, 
	session_type VARCHAR(50) NOT NULL, 
	topic_filter TEXT, 
	difficulty_filter VARCHAR(50), 
	total_questions INTEGER NOT NULL, 
	time_limit_minutes INTEGER, 
	start_time VARCHAR(50) NOT NULL, 
	end_time VARCHAR(50), 
	correct_answers INTEGER, 
	incorrect_answers INTEGER, 
	score_percentage FLOAT, 
	status VARCHAR(50), pass_threshold INTEGER DEFAULT 70, 
	PRIMARY KEY (id), 
	FOREIGN KEY(document_id) REFERENCES documents (id) ON DELETE CASCADE
);
CREATE TABLE user_attempts (
	id INTEGER NOT NULL, 
	question_id INTEGER NOT NULL, 
	session_id INTEGER, 
	selected_answer VARCHAR(50) NOT NULL, 
	is_correct BOOLEAN NOT NULL, 
	time_spent_seconds INTEGER, 
	attempt_date VARCHAR(50), 
	PRIMARY KEY (id), 
	FOREIGN KEY(question_id) REFERENCES questions (id) ON DELETE CASCADE, 
	FOREIGN KEY(session_id) REFERENCES study_sessions (id) ON DELETE SET NULL
);
CREATE UNIQUE INDEX ix_documents_file_id ON documents (file_id);
CREATE INDEX ix_questions_topic_id ON questions (topic_id);
CREATE INDEX ix_questions_difficulty ON questions (difficulty);
CREATE INDEX ix_questions_document_id ON questions (document_id);
CREATE INDEX ix_questions_question_type ON questions (question_type);
CREATE INDEX ix_study_sessions_start_time ON study_sessions (start_time);
CREATE INDEX ix_study_sessions_session_type ON study_sessions (session_type);
CREATE INDEX ix_study_sessions_document_id ON study_sessions (document_id);
CREATE INDEX ix_study_sessions_status ON study_sessions (status);
CREATE INDEX ix_user_attempts_is_correct ON user_attempts (is_correct);
CREATE INDEX ix_user_attempts_attempt_date ON user_attempts (attempt_date);
CREATE INDEX ix_user_attempts_session_id ON user_attempts (session_id);
CREATE INDEX ix_user_attempts_question_id ON user_attempts (question_id);
CREATE INDEX ix_spaced_repetition_next_review_date ON spaced_repetition (next_review_date);
CREATE UNIQUE INDEX ix_spaced_repetition_question_id ON spaced_repetition (question_id);
CREATE UNIQUE INDEX ix_app_settings_setting_key ON app_settings (setting_key);
COMMIT;
